/** The first lines of every generated file. Nothing is ever written over a file lacking it. */
export const HEADER = [
  '<!-- AUTO-GENERATED by @odh-dashboard/extension-map. Do not edit by hand. -->',
  '',
  '> Generated file. Regenerate with `pnpm docs:extension-map`.',
].join('\n');

/**
 * GitHub's anchor slug for a heading: lowercase, every character outside `[a-z0-9 _-]` dropped,
 * spaces turned into dashes.
 */
export const githubAnchor = (heading: string): string =>
  heading
    .toLowerCase()
    .replace(/[^a-z0-9 _-]/g, '')
    .replace(/ /g, '-');

/** Text that is safe inside one line of Markdown: newlines become `<br>`. */
export const escapeInline = (s: string): string => s.replace(/\r?\n/g, '<br>');

/** Text that is safe inside a table cell: table-breaking pipes are escaped too. */
export const escapeCell = (s: string): string => escapeInline(s).replace(/\|/g, '\\|');

/** Collapses runs of whitespace so a declared type fits on one line. */
export const oneLine = (s: string): string => s.replace(/\s+/g, ' ').trim();

/** A Markdown table. Cells are escaped here, so callers pass them unescaped. */
export const table = (headers: string[], rows: string[][]): string =>
  [
    `| ${headers.map(escapeCell).join(' | ')} |`,
    `| ${headers.map(() => '---').join(' | ')} |`,
    ...rows.map((row) => `| ${row.map(escapeCell).join(' | ')} |`),
  ].join('\n');

/** A definition list: what a table row becomes once it would need too many columns. */
export const defList = (items: [string, string][]): string =>
  items.map(([term, value]) => `- **${escapeInline(term)}:** ${escapeInline(value)}`).join('\n');

/** Joins blocks of a page, dropping the ones that produced nothing. */
export const joinBlocks = (blocks: (string | undefined)[]): string =>
  blocks.filter((block): block is string => block !== undefined && block !== '').join('\n\n');
